function accountDateOrder() {
  if (['dmy', 'mdy', 'ymd'].includes(prefs.dateOrder)) return prefs.dateOrder;
  const zone = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
  if (/^(Europe|Africa|Australia)\//.test(zone)) return 'dmy';
  if (/^America\//.test(zone)) return 'mdy';
  if (/^Asia\/(Shanghai|Hong_Kong|Tokyo|Seoul)/.test(zone)) return 'ymd';
  return 'ymd';
}
function formatAccountDate(now = new Date()) {
  const yy = String(now.getFullYear()).slice(-2), mm = String(now.getMonth() + 1).padStart(2, '0'), dd = String(now.getDate()).padStart(2, '0');
  return ({ dmy: `${dd}-${mm}-${yy}`, mdy: `${mm}-${dd}-${yy}`, ymd: `${yy}-${mm}-${dd}` })[accountDateOrder()];
}
