async function loadRecentChats(panel) {
  panel.dataset.loaded = 'true'; panel.replaceChildren(make('p', 'hsbc-recent-state', 'Loading recent chats...'));
  const context = window.SillyTavern?.getContext?.();
  if (!context?.characters || typeof context.getRequestHeaders !== 'function') {
    panel.dataset.loaded = ''; panel.replaceChildren(make('p', 'hsbc-recent-state', 'Chat history is not available right now.')); return;
  }
  try {
    const characterList = Array.from(context.characters, (character, index) => ({ character, index }))
      .filter(({ character }) => character?.avatar)
      .sort((a, b) => timestamp(b.character.date_last_chat) - timestamp(a.character.date_last_chat));
    const headers = context.getRequestHeaders(), allChats = []; let next = 0;
    const worker = async () => {
      while (next < characterList.length) {
        const { character, index } = characterList[next++];
        try {
          const response = await fetch('/api/chats/search', { method: 'POST', headers, body: JSON.stringify({ query: '', avatar_url: character.avatar, group_id: null }), cache: 'no-cache' });
          if (!response.ok) continue;
          const chats = await response.json();
          const chat = [...chats].sort((a, b) => timestamp(b.last_mes) - timestamp(a.last_mes))[0];
          if (chat) allChats.push({ chat, character, characterId: index, lastChatAt: timestamp(character.date_last_chat) || timestamp(chat.last_mes) });
        } catch (error) { console.warn('HSBC theme: chat history lookup failed for one character.', error); }
      }
    };
    await Promise.all(Array.from({ length: Math.min(6, characterList.length) }, worker));
    const uniqueCharacters = new Map();
    for (const entry of allChats) {
      const key = String(entry.character.avatar || entry.characterId);
      const previous = uniqueCharacters.get(key);
      if (!previous || entry.lastChatAt > previous.lastChatAt) uniqueCharacters.set(key, entry);
    }
    const recent = [...uniqueCharacters.values()].sort((a, b) => b.lastChatAt - a.lastChatAt); panel.replaceChildren();
    if (!recent.length) { panel.append(make('p', 'hsbc-recent-state', 'No recent chats found.')); return; }
    const nativeAvatar = characterId => {
      const row = [...document.querySelectorAll('#rm_print_characters_block .character_select')].find(node => Number(node.getAttribute('chid')) === Number(characterId));
      const image = row?.querySelector('.avatar img, img'); if (image?.src) return image.src;
      try { return context.getThumbnailUrl?.('avatar', context.characters[characterId]?.avatar) || ''; } catch { return ''; }
    };
    recent.slice(0, 15).forEach(({ chat, character, characterId, lastChatAt }) => {
      const src = nativeAvatar(characterId);
      const avatar = src ? `<img class="hsbc-recent-avatar" src="${escapeHtml(src)}" alt="">` : `<span class="hsbc-recent-avatar hsbc-recent-avatar-fallback">${ICON.person}</span>`;
      const row = button('', `${avatar}<span class="hsbc-recent-copy"><strong></strong><small></small><time></time></span>${ICON.right}`, async () => {
        row.disabled = true;
        try {
          if (Number(context.characterId) !== Number(characterId)) await context.selectCharacterById?.(Number(characterId));
          await context.openCharacterChat?.(chat.file_name);
          panel.hidden = true; document.querySelector('.hsbc-account-expand')?.setAttribute('aria-expanded', 'false');
        } catch (error) { console.error('HSBC theme: could not open selected recent chat.', error); row.disabled = false; }
      }, 'hsbc-recent-row');
      row.querySelector('.hsbc-recent-copy strong').textContent = character.name || 'Character';
      const snippet = chat.preview_message || chat.last_mes_text || chat.last_mes || chat.file_name || '';
      row.querySelector('.hsbc-recent-copy small').textContent = String(snippet).replace(/\s+/g, ' ').trim();
      const date = new Date(lastChatAt); row.querySelector('.hsbc-recent-copy time').textContent = Number.isFinite(date.getTime()) && lastChatAt > 0 ? new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(date).replace(',', '') : '';
      row.dataset.chatFile = chat.file_name || ''; panel.append(row);
    });
    hsbcWelcomeRecentEnhance(panel);
    if (!panel.hidden) panel.style.maxHeight = `${panel.scrollHeight}px`;
  } catch (error) {
    panel.dataset.loaded = ''; panel.replaceChildren(make('p', 'hsbc-recent-state', 'Chat history could not be loaded. Tap to try again.'));
    panel.onclick = () => { panel.onclick = null; loadRecentChats(panel); };
  }
}
function timestamp(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') { const numeric = Number(value); if (Number.isFinite(numeric) && value.trim() !== '') return numeric; const parsed = Date.parse(value); return Number.isFinite(parsed) ? parsed : 0; }
  return 0;
}

