  page.querySelector('#hsbc-honorific-select').onchange = e => { const persona = personaEntries()[prefs.cardIndex]; if (persona) { localStorage.setItem(`hsbc-tavern.persona-honorific.${persona.id}`, e.target.value); renderCards(); } };
  page.querySelector('#hsbc-card-skin-select').onchange = e => setSkin(e.target.value);
