  page.querySelector('#hsbc-chinese-subtitles').checked = hsbcSubtitlesOn(); // 1.0.40c
  page.querySelector('#hsbc-chinese-subtitles').onchange = e => { hsbcSetSubtitles(e.target.checked); /* 1.0.40c */ page.classList.toggle('is-bilingual', e.target.checked); applyExtensionTranslations(); };
