  if (!title || !name || title.querySelector('.hsbc-picker-chevron')) return;
  const chevron = make('button', 'hsbc-picker-chevron', '<svg viewBox="0 0 14 14" width="14" height="14" aria-hidden="true"><path d="M2 4.75l5 5 5-5" fill="none" stroke="#DB0011" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>');
  chevron.type = 'button'; chevron.setAttribute('aria-label', 'Choose persona'); chevron.setAttribute('aria-haspopup', 'listbox'); chevron.setAttribute('aria-expanded', 'false');
  name.after(chevron); name.classList.add('hsbc-picker-name'); name.setAttribute('role', 'button'); name.tabIndex = 0;
