    page.querySelectorAll('#hsbc-card-list > .hsbc-persona-card.is-row').forEach(row => { const id = people[Number(row.dataset.index)]?.id || ''; row.dataset.personaKey = id; row.classList.toggle('is-current', Boolean(key) && id === key); });
