  const below = box.bottom + 4; const height = menu.offsetHeight; const wanted = below + height > window.innerHeight - 8 ? box.top - height - 4 : below; menu.style.top = `${Math.min(Math.max(8, wanted), Math.max(8, window.innerHeight - height - 8))}px`;
