const HSBC_LANG_INDEX = { en: 0, 'zh-CN': 1, 'zh-TW': 2, yue: 3 };
function hsbcLang() { const l = hsbcExtSettings().language; return HSBC_LANG_INDEX[l] !== undefined ? l : 'en'; }
function t(key) { const row = HSBC_I18N[key]; return row ? (row[HSBC_LANG_INDEX[hsbcLang()]] || row[0]) : key; }
