function hsbcSetLanguage(lang) { hsbcExtSettings().language = HSBC_LANG_INDEX[lang] !== undefined ? lang : 'en'; hsbcSaveExtSettings(); hsbcI18nApply(); }

// ---- 1.0.40 stop button ----
// While SillyTavern generates, the skin's send arrow (#hsbc-footer .hsbc-send) becomes a STOP button. Source of truth = the native state:
// #mes_stop shown (its own computed display, set inline by ST) or #send_but hidden. Watched by a MutationObserver on both (style/class/
// hidden) + ST generation events; while in the stop state it is re-checked every 2 s and on visibilitychange, so it can never stick.
// A click forwards to the real #mes_stop (no own stop logic); Enter does not send while generating; Escape in our input stops (the native
// Escape hotkey needs #mes_stop to be visible, which it is not inside the skin, so nothing fires twice). Idempotent.
// 1.0.44a: no track circle; arc 2px (non-scaling), ~18.7% of the circumference (user: 2/3 of 28%, 1/5 thinner), ~3px outside the disc at 28-30px icon size
const HSBC_STOP_SVG = '<svg class="hsbc-stop-icon" viewBox="0 0 40 40" width="40" height="40" aria-hidden="true" focusable="false">'
  + '<g class="hsbc-stop-spin"><circle class="hsbc-stop-arc" cx="20" cy="20" r="19.8" fill="none" stroke="#DB0011" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-dasharray="23.22 101.18"/></g>'
  + '<circle class="hsbc-stop-disc" cx="20" cy="20" r="14" fill="#DB0011"/>'
  + '<rect class="hsbc-stop-square" x="15" y="15" width="10" height="10" rx="1" fill="none" stroke="#FFFFFF" stroke-width="2"/></svg>';
