  settings.querySelector('.hsbc-theme-welcome input').addEventListener('change', event => { const input = event.target; hsbcStoreWelcomeImage(input.files?.[0], () => showPreview()); input.value = ''; });
  settings.querySelector('.hsbc-theme-reset').addEventListener('click', () => { hsbcExtSettings().welcomeImage = ''; hsbcSaveExtSettings(); hsbcApplyWelcomeImage(); showPreview(); });
