      const host = document.querySelector('#hsbc-native-host');
      if (host && ['showCardsPage', 'openNativePage'].includes(name)) host.append(make('p', 'hsbc-native-unavailable', `${name === 'showCardsPage' ? 'Cards' : 'This'} page could not be displayed. Please reload SillyTavern.`));
